 IF EXISTS (SELECT 1 FROM private.iclub_exam_core_written_tasks_v1 WHERE program_key='economics_9708' AND task_version='economics_9708_written_editorial_candidate_v3_20261027') THEN RAISE EXCEPTION 'Candidate version exists'; END IF;
 IF EXISTS (SELECT 1 FROM private.iclub_exam_written_source_cards_v1 WHERE program_key='economics_9708' AND source_version='economics_sectionA_editorial_v3_20261027') THEN RAISE EXCEPTION 'Source version exists'; END IF;
 IF EXISTS (SELECT 1 FROM private.iclub_exam_written_source_bindings_v1 WHERE program_key='economics_9708' AND task_version='economics_9708_written_editorial_candidate_v3_20261027') THEN RAISE EXCEPTION 'Bindings exist'; END IF;
 IF (SELECT count(*) FROM private.iclub_exam_core_written_access_v1)<>0 OR (SELECT count(*) FROM private.iclub_exam_core_written_plans_v1)<>0 OR (SELECT count(*) FROM private.iclub_exam_core_written_plan_items_v1)<>0 THEN RAISE EXCEPTION 'Runtime assignment baseline changed'; END IF;
END;$preflight$;
WITH d AS (SELECT * FROM jsonb_to_recordset('[{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","source_id":"P2-A-Isara-v1","source_version":"economics_sectionA_editorial_v3_20261027","content":{"en":{"title":"Isara: vegetable price controls and inflation","paragraphs":["Isara has introduced a maximum price of $5 per kilogram for fresh vegetables. Without the ceiling, analysts estimate that the current market would clear near $7. At the controlled price, weekly quantity demanded is 160 thousand kilograms and quantity supplied is 100 thousand kilograms. Illegal resale and long queues have been reported in some districts.","An outbreak of fungal disease reduced the most recent vegetable harvest. The government is considering either removing the price ceiling or subsidising growers. Neither proposal has yet been implemented.","Annual consumer price inflation declined from 8% in Year A to 6% in Year B. Fresh vegetable retail prices fell slightly in Year B, while several other consumer prices continued to rise. These statistics are illustrative, not real-world data."],"table":{"columns":["Indicator","Value"],"rows":[["Maximum retail price (US$/kg)",5],["Estimated market-clearing price (US$/kg)",7],["Demand at price ceiling (thousand kg/week)",160],["Supply at price ceiling (thousand kg/week)",100],["Consumer inflation, Year A (%)",8],["Consumer inflation, Year B (%)",6]],"unit":""}},"ru":{"title":"Исара: потолок цен на овощи и инфляция","paragraphs":["В Исаре установлена максимальная розничная цена свежих овощей — 5 долларов за килограмм. Аналитики оценивают равновесную цену без ограничений примерно в 7 долларов. При цене 5 долларов недельный спрос равен 160 тыс. кг, а предложение — 100 тыс. кг. В некоторых районах отмечены очереди и незаконная перепродажа.","Вспышка грибкового заболевания сократила последний урожай овощей. Правительство рассматривает отмену потолка цены или субсидирование производителей. Ни одна из этих мер пока не принята.","Годовая потребительская инфляция снизилась с 8% в году A до 6% в году B. При этом розничные цены на свежие овощи в году B немного снизились, а цены ряда других потребительских товаров продолжили расти. Все данные вымышлены и используются только для обучения."],"table":{"columns":["Показатель","Значение"],"rows":[["Максимальная розничная цена (долл. США/кг)",5],["Расчётная равновесная цена (долл. США/кг)",7],["Спрос при потолке цены (тыс. кг/неделю)",160],["Предложение при потолке цены (тыс. кг/неделю)",100],["Потребительская инфляция, год A (%)",8],["Потребительская инфляция, год B (%)",6]],"unit":""}},"uz":{"title":"Isara: sabzavot narxini cheklash va inflyatsiya","paragraphs":["Isarada yangi sabzavotning eng yuqori chakana narxi bir kilogramm uchun 5 AQSh dollari qilib belgilangan. Tahlilchilarga ko‘ra, cheklov bo‘lmasa bozor muvozanat narxi taxminan 7 dollar bo‘lardi. 5 dollarlik narxda haftalik talab 160 ming kg, taklif esa 100 ming kg. Ayrim hududlarda navbatlar va noqonuniy qayta sotish kuzatilgan.","Zamburug‘ kasalligi so‘nggi sabzavot hosilini kamaytirdi. Hukumat narx chegarasini bekor qilish yoki yetishtiruvchilarga subsidiya berishni ko‘rib chiqmoqda. Hozircha hech biri joriy etilmagan.","Yillik iste’mol inflyatsiyasi A yilidagi 8% dan B yilida 6% ga tushdi. Shu paytda yangi sabzavotning chakana narxi biroz arzonlashdi, boshqa ayrim iste’mol tovarlari narxi esa oshishda davom etdi. Barcha ma’lumotlar uydirma va faqat o‘quv maqsadida keltirilgan."],"table":{"columns":["Ko‘rsatkich","Qiymat"],"rows":[["Eng yuqori chakana narx (AQSh dollari/kg)",5],["Taxminiy muvozanat narxi (AQSh dollari/kg)",7],["Narx chegarasidagi talab (ming kg/hafta)",160],["Narx chegarasidagi taklif (ming kg/hafta)",100],["Iste’mol inflyatsiyasi, A yil (%)",8],["Iste’mol inflyatsiyasi, B yil (%)",6]],"unit":""}}}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","source_id":"P4-A-Nerava-v1","source_version":"economics_sectionA_editorial_v3_20261027","content":{"en":{"title":"Nerava: depreciation and trade","paragraphs":["Nerava’s currency depreciated from US$0.50 to US$0.40 per nerav over two years. Its statistical office published provisional cross-border trade figures. Trade values below are in billions of US dollars with the same coverage in both years.","Manufacturers import energy and machine parts, so currency depreciation can raise their input costs even as some export prices fall for foreign buyers. The central bank is considering exchange-market intervention, while the labour ministry proposes vocational training. Economists disagree about the timing and magnitude of the effects.","The table covers trade in goods and services only. It excludes primary and secondary income, as well as capital-account and financial-account flows."],"table":{"columns":["Indicator","Year A","Year B"],"rows":[["Exports of goods",30,34],["Imports of goods",46,48],["Exports of services",12,14],["Imports of services",8,9]],"unit":"US$ billions"}},"ru":{"title":"Нерава: снижение курса и внешняя торговля","paragraphs":["Валюта Неравы за два года подешевела с 0,50 до 0,40 доллара США за один нерав. Статистическое ведомство опубликовало предварительные показатели внешней торговли. Значения ниже выражены в миллиардах долларов США и рассчитаны по одинаковой методологии для двух лет.","Производители импортируют энергоносители и комплектующие, поэтому снижение курса может повышать издержки, даже если некоторые экспортные товары дешевеют для зарубежных покупателей. Центральный банк рассматривает валютные операции, а министерство труда предлагает профессиональную подготовку. Экономисты расходятся во мнении о сроках и размерах эффекта.","Таблица охватывает только торговлю товарами и услугами. Она не содержит данных о первичных/вторичных доходах, капитальном и финансовом счетах."],"table":{"columns":["Показатель","Год A","Год B"],"rows":[["Экспорт товаров",30,34],["Импорт товаров",46,48],["Экспорт услуг",12,14],["Импорт услуг",8,9]],"unit":"млрд долларов США"}},"uz":{"title":"Nerava: valyuta qadrsizlanishi va tashqi savdo","paragraphs":["Nerava valyutasi ikki yilda bir nerav uchun 0,50 AQSh dollaridan 0,40 dollargacha qadrsizlandi. Statistika idorasi tashqi savdo bo‘yicha dastlabki ma’lumotlarni e’lon qildi. Quyidagi qiymatlar milliard AQSh dollarida bo‘lib, ikki yil uchun bir xil uslubda hisoblangan.","Ishlab chiqaruvchilar energiya va mashina qismlarini import qiladi. Shu sababli valyuta qadrsizlanishi ayrim eksport tovarlarini xorijliklar uchun arzonlashtirsa-da, ishlab chiqarish xarajatlarini oshirishi mumkin. Markaziy bank valyuta intervensiyasini, mehnat vazirligi esa kasbiy tayyorgarlikni ko‘rib chiqmoqda. Iqtisodchilar ta’sir muddati va miqdori bo‘yicha turlicha fikrda.","Jadval faqat tovar va xizmatlar savdosini qamrab oladi. Birlamchi/ikkilamchi daromadlar, kapital va moliyaviy hisoblar kiritilmagan."],"table":{"columns":["Ko‘rsatkich","A yil","B yil"],"rows":[["Tovarlar eksporti",30,34],["Tovarlar importi",46,48],["Xizmatlar eksporti",12,14],["Xizmatlar importi",8,9]],"unit":"milliard AQSh dollari"}}}}]'::jsonb) AS x(program_key text,version_key text,source_id text,source_version text,content jsonb))
INSERT INTO private.iclub_exam_written_source_cards_v1(program_key,version_key,source_id,source_version,content,content_sha256,status,academic_review,language_review,source_review,release_enabled)
SELECT program_key,version_key,source_id,source_version,content,encode(pg_catalog.sha256(pg_catalog.convert_to(content::text,'UTF8')),'hex'),'draft','pending','pending','pending',false FROM d;
WITH d AS (SELECT * FROM jsonb_to_recordset('[{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.A.a","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Define a market shortage at a given price.","ru":"Дайте определение дефицита товара на рынке при заданной цене.","uz":"Muayyan narxda bozorda tovar taqchilligi nimani anglatishini ta’riflang."},"answer_requirements":{"en":["State that quantity demanded exceeds quantity supplied at the stated price.","Distinguish a shortage from simply having a low stock level."],"ru":["Укажите, что при данной цене величина спроса превышает величину предложения.","Не путайте рыночный дефицит с временно низким запасом товара."],"uz":["Berilgan narxda talab miqdori taklif miqdoridan ortiq bo‘lishini ayting.","Bozor taqchilligini ombordagi vaqtinchalik kam zaxiradan farqlang."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.A.b","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Using the Isara source, calculate the weekly vegetable shortage at the maximum price. Show your working and give your answer in thousand kg per week.","ru":"По данным источника об Исаре рассчитайте недельный дефицит овощей при установленной максимальной цене. Покажите расчёт; ответ дайте в тыс. кг в неделю.","uz":"Isara haqidagi manba ma’lumotlariga asoslanib, eng yuqori belgilangan narxda haftalik sabzavot taqchilligini hisoblang. Hisoblashni ko‘rsating; javobni haftasiga ming kg da yozing."},"answer_requirements":{"en":["Identify demand of 160 and supply of 100 thousand kg per week at $5/kg.","Compute 160 − 100 = 60 thousand kg/week; shortage is not 60% or $60."],"ru":["При $5/кг возьмите спрос 160 и предложение 100 тыс. кг в неделю.","Рассчитайте 160 − 100 = 60 тыс. кг/неделю; это не 60% и не $60."],"uz":["$5/kg narxda talab 160 va taklif 100 ming kg/hafta ekanini toping.","160 − 100 = 60 ming kg/hafta hisoblang; bu 60% ham, $60 ham emas."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.A.c","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Assuming demand is unchanged, explain how the fungal disease would change the market equilibrium for vegetables compared with the equilibrium before the harvest loss. Use a labelled diagram if helpful.","ru":"Предполагая неизменность спроса, объясните, как грибковое заболевание изменит равновесие рынка овощей по сравнению с положением до потери урожая. При необходимости используйте подписанный график.","uz":"Talab o‘zgarmas deb olib, zamburug‘ kasalligi hosil kamayishidan oldingi holatga nisbatan sabzavot bozoridagi muvozanatni qanday o‘zgartirishini tushuntiring. Zarur bo‘lsa, belgilangan grafikdan foydalaning."},"answer_requirements":{"en":["Explain that the crop loss shifts supply left at each price, while demand remains fixed.","Show the higher equilibrium price and lower equilibrium quantity; distinguish equilibrium from the existing binding ceiling.","For a diagram label P, Q, D, S0, S1 and both equilibria."],"ru":["Объясните сдвиг предложения влево вследствие потери урожая при неизменном спросе.","Покажите повышение равновесной цены и снижение равновесного количества; отличайте равновесие от действующего потолка цены.","На графике обозначьте P, Q, D, S0, S1 и оба равновесия."],"uz":["Hosil yo‘qotilishi taklif egri chizig‘ini chapga siljitishini, talab esa o‘zgarmasligini tushuntiring.","Muvozanat narxi oshishi va miqdori kamayishini ko‘rsating; muvozanatni amaldagi narx chegarasidan farqlang.","Grafikda P, Q, D, S0, S1 va ikkala muvozanatni belgilang."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.A.d","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Analyse two different ways in which a binding maximum price could make vegetables harder for consumers to obtain, even though the official price is lower.","ru":"Проанализируйте два различных механизма, из-за которых обязательный потолок цены может затруднить покупателям получение овощей, хотя официальная цена ниже.","uz":"Majburiy eng yuqori narx rasman pastroq bo‘lsa ham, iste’molchilarning sabzavot topishini qiyinlashtirishi mumkin bo‘lgan ikki turli mexanizmni tahlil qiling."},"answer_requirements":{"en":["Develop the shortage channel: Qd > Qs creates queues or non-price rationing.","Develop a separate incentive/allocative channel: lower expected returns can limit deliveries or encourage resale outside official markets.","Link each mechanism to actual access, not merely nominal affordability."],"ru":["Раскройте механизм дефицита: спрос выше предложения ведёт к очередям или неценовому распределению.","Отдельно покажите стимулы производителей/продавцов: меньшая выручка может уменьшить поставки или вывести часть продаж в неофициальный сектор.","Свяжите оба механизма с фактической возможностью купить товар, а не только с указанной ценой."],"uz":["Taqchillik mexanizmini yoritib bering: talab taklifdan ortishi navbat yoki narxsiz taqsimotga olib keladi.","Alohida rag‘bat kanalini tushuntiring: past tushum yetkazib berishni kamaytirishi yoki norasmiy qayta sotuvni kuchaytirishi mumkin.","Ikkala mexanizmni rasmiy arzon narx emas, haqiqiy xarid imkoniyati bilan bog‘lang."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.A.e","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Isara’s annual inflation rate falls from 8% in Year A to 6% in Year B. Explain why this represents disinflation rather than a fall in the overall consumer price level.","ru":"Годовая инфляция в Исаре снизилась с 8% в году A до 6% в году B. Объясните, почему это означает замедление инфляции, а не снижение общего уровня потребительских цен.","uz":"Isarada yillik inflyatsiya A yilidagi 8% dan B yilida 6% ga tushdi. Nima uchun bu narxlarning umumiy pasayishi emas, balki inflyatsiya sur’atining sekinlashishi ekanini tushuntiring."},"answer_requirements":{"en":["Distinguish a positive inflation rate from a falling price level (deflation).","Explain that overall prices still rise in Year B, just at a slower rate.","Avoid treating a fall in one vegetable price as proof of economy-wide deflation."],"ru":["Различите положительную инфляцию и дефляцию — снижение общего уровня цен.","Покажите, что в году B общий уровень цен продолжает расти, но медленнее.","Не считайте падение цены одного вида товара доказательством общей дефляции."],"uz":["Musbat inflyatsiya bilan umumiy narxlar darajasining pasayishi — deflyatsiyani farqlang.","B yilida narxlar baribir oshishini, lekin sekinroq oshishini ko‘rsating.","Bitta tovar narxi pasayishini umumiy deflyatsiya dalili deb qabul qilmang."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.A.f","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Evaluate whether removing Isara’s vegetable price ceiling would necessarily improve access to food for low-income households.","ru":"Оцените, обязательно ли отмена потолка цен на овощи в Исаре улучшит доступ малообеспеченных семей к продуктам питания.","uz":"Isarada sabzavotlarga qo‘yilgan eng yuqori narxni bekor qilish kam daromadli oilalarning oziq-ovqatga kirish imkoniyatini albatta yaxshilaydimi? Baholang."},"answer_requirements":{"en":["Analyse potential benefits: a market-clearing price may increase quantity supplied and reduce queues.","Analyse potential harms: higher legal prices may worsen affordability for poorer households.","Judge conditionally using supply responsiveness and possible targeted support; distinguish access from affordability."],"ru":["Разберите возможный плюс: более высокая рыночная цена может увеличить предложение и сократить очереди.","Разберите риск: более высокая цена может ухудшить доступность по доходу.","Сделайте условный вывод с учётом эластичности предложения и адресной поддержки; различите наличие товара и платёжеспособность."],"uz":["Ijobiy ta’sirni tahlil qiling: bozor narxi taklifni oshirishi va navbatlarni kamaytirishi mumkin.","Salbiy ta’sirni tahlil qiling: yuqoriroq narx kambag‘al oilalarning xarid qobiliyatini pasaytirishi mumkin.","Taklifning moslashuvchanligi va manzilli yordamni hisobga olib, shartli xulosa qiling; mahsulot mavjudligi va uni sotib olish imkoniyatini farqlang."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.B1.a","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Explain the factors that determine the price elasticity of supply of an agricultural product.","ru":"Объясните факторы, определяющие ценовую эластичность предложения сельскохозяйственной продукции.","uz":"Qishloq xo‘jaligi mahsulotining taklif narx elastikligini belgilovchi omillarni tushuntiring."},"answer_requirements":{"en":["Define PES as percentage change in quantity supplied divided by percentage change in price, ceteris paribus.","Explain biological growth cycles and short-run production constraints.","Explain spare land/labour, input availability and time to respond.","Consider perishability and storage capacity; link mechanisms to high/low PES."],"ru":["Дайте определение PES как отношения процентного изменения предложения к процентному изменению цены при прочих равных условиях.","Объясните сезонность и биологические циклы производства.","Проанализируйте наличие земли, труда, ресурсов и время на расширение выпуска.","Учитывайте скоропортимость и возможность хранения, объясняя большую или меньшую PES."],"uz":["PESni boshqa sharoitlar o‘zgarmaganda taklif miqdorining foiz o‘zgarishi narxning foiz o‘zgarishiga nisbati sifatida ta’riflang.","Yetishtirish davri va mavsumiy cheklovlarni tushuntiring.","Yer, ishchi kuchi, resurslar va javob berish vaqtini tahlil qiling.","Tez buzilish va saqlash imkoniyatining PESga ta’sirini ko‘rsating."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.B1.b","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Assess whether a subsidy to food producers is necessarily more effective than a binding maximum price in making essential food affordable to consumers.","ru":"Оцените, всегда ли субсидия производителям продовольствия эффективнее обязательного потолка цены для обеспечения ценовой доступности необходимых продуктов.","uz":"Oziq-ovqat ishlab chiqaruvchilariga subsidiya berish zaruriy mahsulotlarni iste’molchilar uchun arzonlashtirishda majburiy eng yuqori narxdan har doim samaraliroqmi? Baholang."},"answer_requirements":{"en":["Explain how a subsidy reduces producers’ effective costs and can shift market supply right; incidence depends on PED/PES.","Explain how a binding maximum price reduces the official price but may cause excess demand, queues and black markets.","Evaluate budgetary cost, leakage, targeting, time to increase supply and enforcement.","Reach a conditional conclusion distinguishing affordability from physical availability."],"ru":["Покажите, как субсидия снижает эффективные издержки и сдвигает предложение вправо; распределение выгоды зависит от PED/PES.","Покажите, как потолок цены удешевляет товар официально, но создаёт дефицит и теневые рынки.","Оцените бюджетную стоимость, адресность, скорость расширения предложения и контроль.","Сделайте условный вывод, различая низкую цену и фактическое наличие товара."],"uz":["Subsidiya ishlab chiqarish xarajatlarini kamaytirib, taklifni o‘ngga siljitishi mumkinligini; foyda taqsimoti PED/PESga bog‘liqligini tushuntiring.","Majburiy narx chegarasi rasmiy narxni tushirib, taqchillik va norasmiy bozorlarga olib kelishi mumkinligini ko‘rsating.","Byudjet xarajati, manzillilik, ishlab chiqarish kechikishi va nazoratni baholang.","Arzon narx va haqiqiy mavjudlikni farqlab, shartli xulosa qiling."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.B2.a","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Explain how cross elasticity of demand distinguishes substitutes from complements. Illustrate your explanation with one numerical example for each relationship.","ru":"Объясните, как перекрёстная эластичность спроса позволяет различать товары-заменители и взаимодополняющие товары. Приведите по одному числовому примеру каждого вида связи.","uz":"Talabning kesishma elastikligi o‘rnini bosuvchi va bir-birini to‘ldiruvchi tovarlarni qanday ajratib ko‘rsatishini tushuntiring. Har ikki bog‘liqlik uchun bittadan sonli misol keltiring."},"answer_requirements":{"en":["Define XED as percentage change in demand for good B divided by percentage change in price of good A.","For substitutes show positive XED, e.g. +10% / +5% = +2.","For complements show negative XED, e.g. −4% / +5% = −0.8.","Interpret the sign and absolute size; explain why examples need demand shifts, not movements along B’s own demand curve."],"ru":["Дайте формулу XED: процентное изменение спроса на B / процентное изменение цены A.","Для заменителей приведите положительное значение, например +10% / +5% = +2.","Для комплементов приведите отрицательное значение, например −4% / +5% = −0,8.","Объясните знак и модуль коэффициента; речь об изменении спроса на B, а не движении по его кривой."],"uz":["XED formulasini yozing: B tovarga talabning foiz o‘zgarishi / A tovar narxining foiz o‘zgarishi.","O‘rinbosarlar uchun musbat misol keltiring: +10% / +5% = +2.","To‘ldiruvchilar uchun manfiy misol keltiring: −4% / +5% = −0,8.","Koeffitsiyent ishorasi va modulini talqin qiling; B tovarga talab siljishini uning egri chizig‘i bo‘ylab harakat bilan adashtirmang."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.B2.b","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Assess whether a government can predict its revenue from a fixed per-unit indirect tax accurately by knowing only the price elasticity of demand for the taxed good.","ru":"Оцените, может ли государство точно прогнозировать поступления от косвенного налога с фиксированной суммой на единицу товара, зная только ценовую эластичность спроса на облагаемый товар.","uz":"Davlat soliqqa tortiladigan tovarning talab narx elastikligini bilish orqali har bir tovar birligiga qat’iy miqdorda belgilanadigan bilvosita soliqdan tushumni aniq bashorat qila oladimi? Baholang."},"answer_requirements":{"en":["Explain how higher consumer prices and PED affect the post-tax quantity, with incidence depending also on PES.","State the revenue identity for a per-unit tax: tax per unit × units sold after the tax.","Evaluate the influence of supply elasticity, original market size, tax rate, evasion and changes in demand.","Conclude that PED alone is insufficient even when its sign and magnitude are known."],"ru":["Покажите, как PED влияет на количество после налога; налоговое бремя зависит также от PES.","Запишите поступления от налога на единицу как ставка × количество продаж после налога.","Оцените влияние исходного объёма рынка, PES, величины налога, уклонения и сдвигов спроса.","Обоснуйте, почему одного PED недостаточно для точного прогноза."],"uz":["PED soliqdan keyingi hajmga ta’sir qilishini, soliq yuki esa PESga ham bog‘liqligini tushuntiring.","Bir birlikka soliqdan tushum = soliq stavkasi × soliqdan keyingi sotilgan miqdor formulasi keltiring.","Boshlang‘ich bozor hajmi, PES, soliq stavkasi, soliqdan qochish va talab siljishini baholang.","Nima uchun faqat PED aniq prognoz uchun yetarli emasligini asoslang."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.C1.a","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Using an AD/AS framework, explain how an increase in government spending may affect aggregate demand, real output and the price level in the short run.","ru":"Используя модель AD/AS, объясните, как увеличение государственных расходов может повлиять на совокупный спрос, реальный выпуск и уровень цен в краткосрочном периоде.","uz":"AD/AS modeli yordamida davlat xarajatlarining oshishi qisqa muddatda yalpi talab, real ishlab chiqarish va narxlar darajasiga qanday ta’sir qilishini tushuntiring."},"answer_requirements":{"en":["Identify government expenditure (G) as a component of AD and explain the rightward shift when other factors are held constant.","Explain increases in equilibrium output and possible increases in the price level depending on AS position/spare capacity.","Illustrate AD0→AD1 against AS with correctly labelled axes if using a diagram.","Distinguish a demand-side increase in actual output from a lasting rise in productive capacity."],"ru":["Укажите G как компонент AD и объясните сдвиг AD вправо при прочих равных.","Объясните рост равновесного выпуска и возможный рост цен в зависимости от предложения и свободных мощностей.","При графическом ответе подпишите оси и AD0→AD1 относительно AS.","Отличайте рост фактического выпуска из-за AD от устойчивого увеличения производственного потенциала."],"uz":["G yalpi talabning tarkibiy qismi ekanini ko‘rsating va boshqa sharoitlar o‘zgarmasa AD o‘ngga siljishini tushuntiring.","Taklif va bo‘sh quvvatlarga qarab real ishlab chiqarish hamda narxlar darajasi qanday o‘zgarishini ko‘rsating.","Grafikda o‘qlar va AD0→AD1, ASni aniq belgilang.","AD ortishi tufayli haqiqiy ishlab chiqarish ko‘payishini ishlab chiqarish salohiyatining uzoq muddatli o‘sishidan farqlang."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.C1.b","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Assess whether supply-side policies are likely to be more effective than increased government spending on goods and services in promoting economic growth.","ru":"Оцените, будут ли меры политики предложения эффективнее увеличения государственных закупок товаров и услуг для стимулирования экономического роста.","uz":"Taklifni rag‘batlantiruvchi siyosat davlatning tovar va xizmatlarga xarajatlarini oshirishga qaraganda iqtisodiy o‘sishni kuchaytirishda samaraliroq bo‘ladimi? Baholang."},"answer_requirements":{"en":["Compare AD stimulus from government purchases with LRAS/productivity improvements from training or infrastructure.","Distinguish short-run actual growth from longer-run potential growth.","Discuss delays, budget constraints, spare capacity and possible inflationary pressures.","Give a conditional judgement based on the economy’s binding constraint."],"ru":["Сравните стимул AD от госзакупок с ростом производительности и LRAS от обучения или инфраструктуры.","Различите краткосрочный фактический рост и долгосрочный потенциальный рост.","Оцените задержки, бюджетные ограничения, загрузку мощностей и инфляционные риски.","Сделайте вывод исходя из главного ограничения экономики."],"uz":["Davlat xaridlari orqali AD oshishi va ta’lim/infratuzilma orqali unumdorlik hamda LRAS oshishini taqqoslang.","Qisqa muddatli haqiqiy o‘sishni uzoq muddatli potensial o‘sishdan farqlang.","Vaqt kechikishi, byudjet cheklovi, quvvatlar bandligi va inflyatsiyani baholang.","Iqtisodiyotdagi asosiy cheklovdan kelib chiqib shartli xulosa qiling."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.C2.a","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Explain two economically distinct reasons why a country might have a deficit on the current account of its balance of payments.","ru":"Объясните две экономически различные причины дефицита счёта текущих операций платёжного баланса страны.","uz":"Mamlakat to‘lov balansining joriy hisobida taqchillik yuzaga kelishining iqtisodiy jihatdan farqli ikkita sababini tushuntiring."},"answer_requirements":{"en":["Define current account components: goods, services, primary income and secondary income.","Develop one channel, such as import demand exceeding export receipts due to weak competitiveness or strong domestic incomes.","Develop a different channel, such as an adverse export price shock or net income transfers abroad.","Explain how each lowers the overall current account balance."],"ru":["Назовите состав текущего счёта: товары, услуги, первичные и вторичные доходы.","Разберите один механизм, например превышение импорта над экспортом при низкой конкурентоспособности.","Разберите другой механизм, например падение экспортных цен или чистый отток доходов.","Для каждого покажите воздействие на общий баланс текущего счёта."],"uz":["Joriy hisob tarkibini sanang: tovarlar, xizmatlar, birlamchi va ikkilamchi daromadlar.","Bitta sababni oching, masalan raqobatbardoshlik sustligi tufayli importning eksportdan ortishi.","Boshqa sababni oching, masalan eksport narxi pasayishi yoki daromadlarning sof chiqib ketishi.","Har birining umumiy joriy hisob balansiga ta’sirini tushuntiring."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P2","task_key":"P2.C2.b","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Assess whether a depreciation of a floating exchange rate is likely to reduce a persistent current account deficit.","ru":"Оцените, насколько вероятно, что снижение курса при плавающем валютном режиме сократит устойчивый дефицит текущего счёта.","uz":"Suzuvchi valyuta kursining qadrsizlanishi joriy hisobdagi davomli taqchillikni kamaytirishi qanchalik ehtimol ekanini baholang."},"answer_requirements":{"en":["Explain relative foreign-currency export prices and domestic-currency import prices after depreciation.","Analyse how export and import quantity responses depend on demand responsiveness and production capacity.","Consider imported inputs, inflation and time to adjust, while recognising other current account components.","Give a conditional judgement based on responsiveness, time to adjust and the relative importance of other current-account flows."],"ru":["Объясните изменение экспортных цен в валюте покупателей и импортных цен в национальной валюте.","Разберите реакцию объёмов с учётом эластичности спроса и возможностей отечественных производителей.","Оцените импортные ресурсы, инфляцию, задержки и другие части текущего счёта.","Дайте условный вывод с учётом реакции спроса, временных задержек и других статей текущего счёта."],"uz":["Qadrsizlanishdan keyin eksport narxi xorijiy valyutada, import narxi milliy valyutada qanday o‘zgarishini tushuntiring.","Eksport va import hajmi javobini talab elastikligi va mahalliy ishlab chiqarish quvvatlari bilan bog‘lang.","Import resurslari, inflyatsiya, vaqt kechikishi va joriy hisobning boshqa qismlarini baholang.","Talabning munosabati, moslashish muddati va joriy hisobning boshqa oqimlarini hisobga olib, shartli xulosa chiqaring."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P4","task_key":"P4.A.a","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Using the Nerava data, calculate the Year B goods-and-services trade balance and the change since Year A. Explain one limitation of using this change to judge whether exchange-market intervention is justified.","ru":"По данным Неравы рассчитайте торговый баланс товаров и услуг за год B и изменение с года A. Объясните одно ограничение использования этого результата при решении о валютной интервенции.","uz":"Nerava ma’lumotlari asosida B yilidagi tovar va xizmatlar savdo balansini hamda A yiliga nisbatan o‘zgarishini hisoblang. Nima uchun bu ko‘rsatkichning o‘zi valyuta bozoriga intervensiya zarurligini aniqlash uchun yetarli emasligini tushuntiring."},"answer_requirements":{"en":["Calculate Year A: (30 + 12) − (46 + 8) = −12 US$bn.","Calculate Year B: (34 + 14) − (48 + 9) = −9 US$bn; improvement of +3 US$bn.","Explain why trade figures alone cannot establish the current-account position or justify exchange-market intervention without income flows, capital and financial flows, policy aims and market conditions."],"ru":["Год A: (30 + 12) − (46 + 8) = −12 млрд долл. США.","Год B: (34 + 14) − (48 + 9) = −9 млрд; улучшение на 3 млрд.","Поясните, что по торговым данным нельзя установить сальдо текущего счёта или обосновать валютную интервенцию без данных о доходах, капитальных и финансовых потоках, целях политики и рыночных условиях."],"uz":["A yil: (30 + 12) − (46 + 8) = −12 mlrd AQSh dollari.","B yil: (34 + 14) − (48 + 9) = −9 mlrd; yaxshilanish +3 mlrd.","Daromad oqimlari, kapital va moliyaviy hisoblar, siyosat maqsadlari hamda bozor sharoitlari noma’lum bo‘lsa, faqat savdo ko‘rsatkichidan joriy hisob saldosini yoki intervensiya zaruratini aniqlab bo‘lmasligini tushuntiring."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P4","task_key":"P4.A.b","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Nerava has a deficit in its trade in goods and services. Explain one difference between an expenditure-switching policy and an expenditure-reducing policy that Nerava could consider, giving one relevant example of each.","ru":"В Нераве наблюдается дефицит торговли товарами и услугами. Объясните одно различие между политикой переключения расходов с импортных на отечественные товары и политикой сокращения совокупных расходов, которые Нерава могла бы рассмотреть. Приведите по одному подходящему примеру каждого подхода.","uz":"Neravaning tovarlar va xizmatlar savdosida taqchillik mavjud. Nerava ko‘rib chiqishi mumkin bo‘lgan xarajatlarni importdan mahalliy mahsulotlarga yo‘naltirish siyosati bilan yalpi xarajatlarni qisqartirish siyosati o‘rtasidagi bitta farqni tushuntiring. Har bir yondashuvga bittadan mos misol keltiring."},"answer_requirements":{"en":["Explain expenditure-switching as redirecting spending from imported products towards domestically produced substitutes, rather than simply reducing total spending.","Give an appropriate switching example, such as a tariff on imports, and explain the intended effect on imports or domestic production.","Explain expenditure-reducing as lowering aggregate demand/income and thereby import demand; give an appropriate example, such as contractionary fiscal policy.","Relate both mechanisms to Nerava’s goods-and-services trade deficit; do not assert that its full balance of payments is in deficit, as that cannot be inferred from the source."],"ru":["Объясните, что переключение расходов означает замещение импорта отечественными товарами, а не простое сокращение общего объёма расходов.","Приведите пример такой меры (например, импортную пошлину) и объясните её возможный эффект на импорт или местное производство.","Объясните, что политика сокращения расходов снижает совокупный спрос и, следовательно, спрос на импорт; приведите пример сдерживающей бюджетно-налоговой политики.","Свяжите оба подхода с дефицитом торговли товарами и услугами Неравы; не утверждайте, что из этих данных известны все статьи платёжного баланса."],"uz":["Xarajatlarni importdan mahalliy mahsulotlarga yo‘naltirish yalpi xarajatlarni oddiygina kamaytirishdan qanday farq qilishini tushuntiring.","Masalan, import bojini ko‘rsating va uning import yoki mahalliy ishlab chiqarishga ehtimoliy ta’sirini tushuntiring.","Yalpi xarajatlarni qisqartirish siyosati yalpi talab va importga talabni kamaytirishini tushuntiring; masalan, cheklovchi fiskal siyosatni keltiring.","Ikkala usulni Neravaning tovarlar va xizmatlar savdosidagi taqchillik bilan bog‘lang; shu jadvaldan butun to‘lov balansi tarkibini aniqlab bo‘lmasligini qayd eting."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P4","task_key":"P4.A.c","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Using Nerava’s source, analyse how the Marshall–Lerner condition and J-curve adjustment could affect the trade balance after depreciation. Explain why the observed improvement does not by itself prove causation.","ru":"Опираясь на источник о Нераве, проанализируйте, как условие Маршалла—Лернера и динамика J-кривой могут влиять на торговый баланс после снижения курса. Объясните, почему наблюдаемое улучшение само по себе не доказывает причинность.","uz":"Nerava manbasiga tayangan holda, kurs qadrsizlanishidan keyin Marshall–Lerner sharti va J-egri chizig‘i savdo balansiga qanday ta’sir qilishini tahlil qiling. Kuzatilgan yaxshilanishning o‘zi sabab-oqibatni isbotlamasligini tushuntiring."},"answer_requirements":{"en":["Explain the Marshall–Lerner elasticity condition as a standard long-run benchmark under its simplifying assumptions; with an initial trade deficit, the elasticity sum alone is not a universal guarantee.","Describe a possible short-run deterioration as contract volumes adjust slowly, followed by later improvement (J-curve).","Refer correctly to the −12 to −9 US$bn data and rising import input costs; avoid inferring causation from correlation."],"ru":["Объясните условие Маршалла—Лернера как долгосрочный ориентир при упрощающих предпосылках; при исходном торговом дефиците одна лишь сумма эластичностей не гарантирует улучшения.","Опишите возможное первоначальное ухудшение из-за медленной реакции объёмов и последующее улучшение (J-кривая).","Используйте данные −12 → −9 млрд и рост стоимости импортных ресурсов; не путайте совпадение с доказанной причинностью."],"uz":["Marshall–Lerner shartini soddalashtiruvchi taxminlar asosidagi uzoq muddatli mezon sifatida tushuntiring; boshlang‘ich savdo taqchilligi bo‘lsa, elastikliklar yig‘indisi yaxshilanishni o‘z-o‘zidan kafolatlamaydi.","Hajmlar sekin moslashganda avval yomonlashish, keyin yaxshilanish (J-egri chizig‘i) ehtimolini ko‘rsating.","−12 dan −9 mlrdga o‘zgarish va import resurslari qimmatlashuvini to‘g‘ri talqin qiling; bog‘liqlikni sabab sifatida qabul qilmang."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P4","task_key":"P4.A.d","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Assess whether investment in vocational training is more likely than short-term central-bank intervention in the exchange market to improve Nerava’s long-run productive capacity and external competitiveness.","ru":"Оцените, более ли вероятно, что инвестиции в профессиональное обучение, чем краткосрочные валютные операции центрального банка, повысят долгосрочный производственный потенциал Неравы и её внешнюю конкурентоспособность.","uz":"Kasbiy ta’limga investitsiya qisqa muddatli markaziy bank valyuta bozoriga aralashuvidan ko‘ra Neravaning uzoq muddatli ishlab chiqarish salohiyati va tashqi raqobatbardoshligini ko‘proq oshiradimi? Baholang."},"answer_requirements":{"en":["Analyse training → worker productivity → lower unit costs / greater capacity / export competitiveness, subject to time lags.","Analyse what intervention may change in exchange-rate volatility or competitiveness, given unknown regime and reserves.","Evaluate funding costs, imported machinery, implementation delays and demand for skills.","Conclude conditionally, not that either policy always works."],"ru":["Покажите цепочку обучение → производительность → удельные издержки/мощности → конкурентоспособность.","Разберите возможные краткосрочные эффекты валютной интервенции с оговоркой о неизвестном режиме и резервах.","Оцените бюджетные затраты, импортное оборудование, лаги и востребованность навыков.","Дайте условный вывод, не утверждая универсального преимущества."],"uz":["Ta’lim → unumdorlik → birlik xarajatlar/quvvat → eksport raqobatbardoshligi bog‘lanishini tahlil qiling.","Valyuta intervensiyasining qisqa muddatli ta’sirini kurs rejimi va zaxiralar noma’lumligini hisobga olib tahlil qiling.","Mablag‘, import uskunalari, kechikish va ko‘nikmalarga talabni baholang.","Har ikkala siyosat ham hamisha samarali deb da’vo qilmasdan shartli xulosa qiling."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P4","task_key":"P4.B1","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Assess the view that an oligopolistic market is necessarily less economically efficient than a perfectly competitive market.","ru":"Оцените утверждение, что олигополистический рынок обязательно экономически менее эффективен, чем рынок совершенной конкуренции.","uz":"Oligopolistik bozor mukammal raqobat bozoriga nisbatan albatta iqtisodiy jihatdan samarasizroq degan fikrni baholang."},"answer_requirements":{"en":["Distinguish allocative efficiency (P=MC), productive efficiency (minimum AC) and dynamic efficiency.","Analyse possible price above MC, restricted output, collusion and barriers to entry in oligopoly.","Analyse countervailing scale economies, R&D, innovation and potential competition.","Use justified diagrams where appropriate; compare short-/long-run and qualify assumptions of perfect competition.","Reach a conditional judgement rather than treating oligopoly as automatically inefficient."],"ru":["Различите аллокативную (P=MC), производственную (минимум AC) и динамическую эффективность.","Разберите P>MC, ограничения выпуска, сговор и барьеры входа.","Сопоставьте эффект масштаба, исследования, инновации и потенциальную конкуренцию.","При необходимости используйте подписанные графики и различите кратко- и долгосрочный периоды.","Сформулируйте условный вывод, не отождествляя олигополию с неэффективностью."],"uz":["Taqsimlash (P=MC), ishlab chiqarish (AC minimumi) va dinamik samaradorlikni farqlang.","Oligopoliyada P>MC, ishlab chiqarish cheklovi, kelishuv va kirish to‘siqlarini tahlil qiling.","Miqyos tejamkorligi, tadqiqot, innovatsiya va potensial raqobatni qarshi dalil sifatida ko‘rsating.","Zarur bo‘lsa belgilangan grafiklar va qisqa/uzoq muddat farqidan foydalaning.","Oligopoliyani avtomatik samarasiz deb bilmay, shartli xulosa qiling."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P4","task_key":"P4.B2","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Evaluate whether a tax on industrial output is the most effective policy for correcting a negative externality of production.","ru":"Оцените, является ли налог на промышленный выпуск наиболее эффективной мерой исправления отрицательного внешнего эффекта производства.","uz":"Sanoat ishlab chiqarishidagi salbiy tashqi ta’sirni tuzatishda mahsulotga soliq eng samarali siyosatmi? Baholang."},"answer_requirements":{"en":["Explain marginal external cost: MSC=MPC+MEC, with socially optimal Q below market Q if MEC>0.","Analyse a Pigouvian-style tax, incentives, output reduction and welfare loss on an MPC/MSC/MPB diagram.","Evaluate the difficulty of measuring MEC, enforcement, distributional effects and government failure.","Compare at least one plausible alternative: emissions permits, regulation, property rights or cleaner technology support.","Reach a conditional policy judgement including conditions under which each approach works."],"ru":["Объясните MEC и равенство MSC=MPC+MEC; при внешнем ущербе общественно оптимальный выпуск ниже рыночного.","Разберите корректирующий налог и сокращение избыточного выпуска на графике MPC/MSC/MPB.","Оцените сложности измерения MEC, исполнения, распределения бремени и провалов государства.","Сравните с разрешениями на выбросы, нормами, правами собственности или поддержкой чистых технологий.","Сделайте вывод исходя из условий эффективности мер."],"uz":["MEC va MSC=MPC+MECni tushuntiring; salbiy tashqi xarajatda ijtimoiy maqbul ishlab chiqarish bozor hajmidan pastligini ko‘rsating.","Tuzatuvchi soliq ta’siri va farovonlik yo‘qotishini MPC/MSC/MPB grafikda tahlil qiling.","MECni o‘lchash, nazorat, yuk taqsimoti va hukumat muvaffaqiyatsizligi muammolarini baholang.","Emissiya ruxsatlari, tartibga solish, mulk huquqi yoki toza texnologiya yordamiga solishtiring.","Qaysi sharoitda qaysi siyosat kuchliroq ekaniga shartli xulosa qiling."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P4","task_key":"P4.C1","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Assess how far monetary policy can achieve sustained economic growth in an open economy without creating additional inflationary pressure.","ru":"Оцените, в какой степени денежно-кредитная политика способна обеспечить устойчивый экономический рост открытой экономики без дополнительного инфляционного давления.","uz":"Ochiq iqtisodiyotda pul-kredit siyosati qo‘shimcha inflyatsiya bosimini yuzaga keltirmasdan barqaror iqtisodiy o‘sishni qanchalik ta’minlay olishini baholang."},"answer_requirements":{"en":["Analyse transmission from interest rates/credit to consumption, investment, AD and actual output.","In an open economy, analyse exchange-rate effects, net exports and imported inflation.","Distinguish short-run AD-led recovery from long-run potential growth determined by supply/productivity.","Evaluate spare capacity, expectations, banking conditions, capital flows, lags and possible conflicts with price stability.","Conclude with economic conditions and complementary supply-side policy."],"ru":["Объясните передачу ставок/кредита через потребление, инвестиции, AD и фактический выпуск.","Для открытой экономики учтите валютный курс, чистый экспорт и импортируемую инфляцию.","Различите краткосрочное восстановление и рост потенциального выпуска в долгом периоде.","Оцените свободные мощности, ожидания, состояние банков, потоки капитала, лаги и конфликт с инфляцией.","Дайте условный вывод с возможной ролью политики предложения."],"uz":["Foiz stavkalari/kredit → iste’mol, investitsiya, AD va haqiqiy ishlab chiqarish uzatish mexanizmini tahlil qiling.","Ochiq iqtisodiyotda valyuta kursi, sof eksport va import inflyatsiyasini ko‘ring.","Qisqa muddatli AD tiklanishini uzoq muddatli potensial o‘sishdan ajrating.","Bo‘sh quvvatlar, kutilmalar, banklar holati, kapital oqimlari, vaqt kechikishi va inflyatsiya ziddiyatini baholang.","Taklif siyosatining o‘rni bilan shartli xulosa qiling."]}},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","paper_code":"P4","task_key":"P4.C2","task_version":"economics_9708_written_editorial_candidate_v3_20261027","questions":{"en":"Evaluate the view that real GDP per head should be the primary indicator used to assess a country’s economic development.","ru":"Оцените утверждение, что реальный ВВП на душу населения должен быть главным показателем экономического развития страны.","uz":"Real aholi jon boshiga YaIM mamlakat iqtisodiy rivojlanishini baholashda asosiy ko‘rsatkich bo‘lishi kerak degan fikrni baholang."},"answer_requirements":{"en":["Explain real GDP per head and the purpose of inflation adjustment and cross-country PPP comparison.","Analyse what it captures about average material output and what it misses: distribution, unpaid production, quality of life and environment.","Compare informative alternatives such as HDI, MPI, health/education or sustainability metrics and their limitations.","Recognise trade-offs between comparability, coverage, reliability and multi-dimensional development.","Reach a nuanced conclusion about using GDP per head alongside other indicators."],"ru":["Дайте определение реального ВВП на человека и роль поправки на инфляцию и ППС для международных сравнений.","Разберите, что измеряет средний объём выпуска, и что скрывается: распределение доходов, неоплаченный труд, качество жизни и экология.","Сравните с ИЧР, индексом многомерной бедности, показателями здоровья/образования и устойчивости, отметив ограничения.","Оцените сопоставимость и качество статистики.","Сделайте аргументированный вывод об использовании ВВП вместе с другими индикаторами."],"uz":["Real jon boshiga YaIMni, inflyatsiya tuzatishi va davlatlararo taqqoslashda xarid qobiliyati paritetini (PPP) tushuntiring.","O‘rtacha ishlab chiqarish o‘lchanishini, biroq tengsizlik, haq to‘lanmaydigan mehnat, turmush sifati va ekologiya yashirin qolishini tahlil qiling.","HDI, ko‘p o‘lchovli kambag‘allik indeksi (MPI), sog‘liq, ta’lim va barqarorlik ko‘rsatkichlarini solishtiring.","Ma’lumotlarning qiyoslanuvchanligi va ishonchliligini baholang.","YaIMni boshqa ko‘rsatkichlar bilan birga ishlatish haqida asosli xulosa qiling."]}}]'::jsonb) AS x(program_key text,version_key text,paper_code text,task_key text,task_version text,questions jsonb,answer_requirements jsonb))
INSERT INTO private.iclub_exam_core_written_tasks_v1(program_key,version_key,paper_code,task_key,task_version,questions,answer_requirements,status,academic_review,language_review,source_review,release_enabled)
SELECT program_key,version_key,paper_code,task_key,task_version,questions,answer_requirements,'draft','pending','pending','pending',false FROM d;
WITH d AS (SELECT * FROM jsonb_to_recordset('[{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","task_key":"P2.A.a","task_version":"economics_9708_written_editorial_candidate_v3_20261027","source_id":"P2-A-Isara-v1","source_version":"economics_sectionA_editorial_v3_20261027"},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","task_key":"P2.A.b","task_version":"economics_9708_written_editorial_candidate_v3_20261027","source_id":"P2-A-Isara-v1","source_version":"economics_sectionA_editorial_v3_20261027"},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","task_key":"P2.A.c","task_version":"economics_9708_written_editorial_candidate_v3_20261027","source_id":"P2-A-Isara-v1","source_version":"economics_sectionA_editorial_v3_20261027"},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","task_key":"P2.A.d","task_version":"economics_9708_written_editorial_candidate_v3_20261027","source_id":"P2-A-Isara-v1","source_version":"economics_sectionA_editorial_v3_20261027"},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","task_key":"P2.A.e","task_version":"economics_9708_written_editorial_candidate_v3_20261027","source_id":"P2-A-Isara-v1","source_version":"economics_sectionA_editorial_v3_20261027"},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","task_key":"P2.A.f","task_version":"economics_9708_written_editorial_candidate_v3_20261027","source_id":"P2-A-Isara-v1","source_version":"economics_sectionA_editorial_v3_20261027"},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","task_key":"P4.A.a","task_version":"economics_9708_written_editorial_candidate_v3_20261027","source_id":"P4-A-Nerava-v1","source_version":"economics_sectionA_editorial_v3_20261027"},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","task_key":"P4.A.b","task_version":"economics_9708_written_editorial_candidate_v3_20261027","source_id":"P4-A-Nerava-v1","source_version":"economics_sectionA_editorial_v3_20261027"},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","task_key":"P4.A.c","task_version":"economics_9708_written_editorial_candidate_v3_20261027","source_id":"P4-A-Nerava-v1","source_version":"economics_sectionA_editorial_v3_20261027"},{"program_key":"economics_9708","version_key":"economics_2026_2028_v1","task_key":"P4.A.d","task_version":"economics_9708_written_editorial_candidate_v3_20261027","source_id":"P4-A-Nerava-v1","source_version":"economics_sectionA_editorial_v3_20261027"}]'::jsonb) AS x(program_key text,version_key text,task_key text,task_version text,source_id text,source_version text))
INSERT INTO private.iclub_exam_written_source_bindings_v1(program_key,version_key,task_key,task_version,source_id,source_version,content_sha256)
SELECT d.program_key,d.version_key,d.task_key,d.task_version,d.source_id,d.source_version,s.content_sha256 FROM d JOIN private.iclub_exam_written_source_cards_v1 s
 ON s.program_key=d.program_key AND s.version_key=d.version_key AND s.source_id=d.source_id AND s.source_version=d.source_version;
DO $audit$ BEGIN
 IF (SELECT count(*) FROM private.iclub_exam_core_written_tasks_v1 WHERE program_key='economics_9708')<>44 THEN RAISE EXCEPTION 'Economics total mismatch'; END IF;
 IF (SELECT count(*) FROM private.iclub_exam_core_written_tasks_v1 WHERE program_key='economics_9708' AND task_version='economics_9708_written_editorial_candidate_v3_20261027' AND status='draft' AND NOT release_enabled AND academic_review='pending' AND language_review='pending' AND source_review='pending' AND questions ?& ARRAY['en','ru','uz'] AND answer_requirements ?& ARRAY['en','ru','uz'])<>22 THEN RAISE EXCEPTION 'Task candidate status/locale mismatch'; END IF;
 IF (SELECT count(*) FROM private.iclub_exam_written_source_cards_v1 WHERE program_key='economics_9708' AND source_version='economics_sectionA_editorial_v3_20261027' AND status='draft' AND NOT release_enabled AND academic_review='pending' AND language_review='pending' AND source_review='pending' AND content ?& ARRAY['en','ru','uz'] AND private.iclub_exam_written_source_locale_valid_v1(content,'en') AND private.iclub_exam_written_source_locale_valid_v1(content,'ru') AND private.iclub_exam_written_source_locale_valid_v1(content,'uz') AND content_sha256=encode(pg_catalog.sha256(pg_catalog.convert_to(content::text,'UTF8')),'hex'))<>2 THEN RAISE EXCEPTION 'Source locale or hash mismatch'; END IF;
 IF (SELECT count(*) FROM private.iclub_exam_written_source_bindings_v1 WHERE program_key='economics_9708' AND task_version='economics_9708_written_editorial_candidate_v3_20261027')<>10 THEN RAISE EXCEPTION 'Bindings count mismatch'; END IF;
 IF (SELECT count(*) FROM private.iclub_exam_core_written_tasks_v1 WHERE program_key='economics_9708' AND task_version<>'economics_9708_written_editorial_candidate_v3_20261027')<>22 THEN RAISE EXCEPTION 'Historic versions changed'; END IF;
 IF (SELECT count(*) FROM private.iclub_exam_core_written_tasks_v1 WHERE program_key='economics_9708' AND release_enabled)<>0 THEN RAISE EXCEPTION 'Unexpected publication'; END IF;
 IF (SELECT count(*) FROM private.iclub_exam_core_written_access_v1)<>0 OR (SELECT count(*) FROM private.iclub_exam_core_written_plans_v1)<>0 OR (SELECT count(*) FROM private.iclub_exam_core_written_plan_items_v1)<>0 THEN RAISE EXCEPTION 'Unexpected learner assignment'; END IF;
END;$audit$;
COMMIT;